import React from 'react';

export default function Navbar({onNavigate,onLogout,user}){
  return (
    <nav className="nav">
      <div className="brand" onClick={()=>onNavigate('home')}>NGO Portal</div>
      <div className="links">
        <button onClick={()=>onNavigate('home')}>Home</button>
        <button onClick={()=>onNavigate('about')}>About Us</button>
        <button onClick={()=>onNavigate('events')}>Events</button>
        {!user && <button onClick={()=>onNavigate('login')}>Login</button>}
        {!user && <button onClick={()=>onNavigate('register')}>Register</button>}
        {user && <button onClick={()=>onNavigate('dashboard')}>Dashboard</button>}
        {user && <button onClick={onLogout}>Logout</button>}
      </div>
    </nav>
  );
}
